import { WebPlugin } from "@capacitor/core";
import { CapacitorOnnxWeb } from "./index";
export class WrapperCapacitorOnnxWeb extends WebPlugin {
    constructor() {
        super(...arguments);
        this.engine = new CapacitorOnnxWeb();
    }
    async loadModel(input) {
        return await this.engine.loadModel(input);
    }
    async run(input) {
        return await this.engine.run(input);
    }
    async release(input) {
        await this.engine.release(input);
    }
}
